static s32 s_aiGraphRequireSafetyDetectionNode(const char *name,
	s32 node_count)
{
	char reason[128];

	if (!s_ActiveScenarioGraphs.level_graph_active) {
		return 0;
	}
	if (node_count != 1) {
		snprintf(reason, sizeof(reason), "missing scenario.ai.condition.%s node",
			name);
		s_aiGraphRuntimeFailure(name, reason);
		return -1;
	}
	if (!s_ActiveScenarioGraphs.ai_lists_path[0]) {
		s_aiGraphRuntimeFailure(name, "missing ai/ailists.json source");
		return -1;
	}
	return 1;
}

static s32 s_aiGraphSafety2Score(struct chrdata *chr, s32 *out_nearby,
	s32 *out_chr_count, s32 *out_source_chr, s32 *out_checked_chrs,
	s32 *out_score)
{
	s16 *chrnums;
	s32 chr_count = 0;
	s32 source_chr = -1;
	s32 checked_chrs = 0;
	s32 score = 6;
	s32 numnearby = 0;

	if (out_chr_count) {
		*out_chr_count = 0;
	}
	if (out_source_chr) {
		*out_source_chr = -1;
	}
	if (out_checked_chrs) {
		*out_checked_chrs = 0;
	}
	if (out_score) {
		*out_score = 0;
	}
	if (!chr || !out_nearby) {
		if (out_nearby) {
			*out_nearby = 0;
		}
		return 1;
	}
	if (!s_aiGraphRequireRuntimeCharacterPointer("if_safety2_less_than",
			chr, &chr_count, &source_chr)) {
		return 0;
	}
	if (chrGetNumArghs(chr) > 0) {
		score -= 2;
	}
	switch (bgunGetWeaponNum(HAND_RIGHT)) {
	case WEAPON_FALCON2:
	case WEAPON_FALCON2_SILENCER:
	case WEAPON_FALCON2_SCOPE:
	case WEAPON_MAGSEC4:
	case WEAPON_MAULER:
	case WEAPON_PHOENIX:
	case WEAPON_DY357MAGNUM:
	case WEAPON_DY357LX:
	case WEAPON_CROSSBOW:
		break;
	case WEAPON_CMP150:
	case WEAPON_CYCLONE:
	case WEAPON_CALLISTO:
	case WEAPON_RCP120:
	case WEAPON_LAPTOPGUN:
	case WEAPON_DRAGON:
	case WEAPON_K7AVENGER:
	case WEAPON_AR34:
	case WEAPON_SUPERDRAGON:
	case WEAPON_SHOTGUN:
	case WEAPON_SNIPERRIFLE:
		score--;
		break;
	case WEAPON_REAPER:
	case WEAPON_FARSIGHT:
	case WEAPON_DEVASTATOR:
	case WEAPON_ROCKETLAUNCHER:
	case WEAPON_SLAYER:
		score -= 2;
		break;
	default:
		score++;
		break;
	}
	chrnums = teamGetChrIds(chr->team);
	if (chrnums) {
		for (; *chrnums != -2; chrnums++) {
			struct chrdata *nearby = chrFindByLiteralId(*chrnums);

			if (nearby) {
				if (!s_aiGraphRequireRuntimeCharacterPointer(
						"if_safety2_less_than", nearby,
						&chr_count, NULL)) {
					return 0;
				}
				checked_chrs++;
			}
			if (nearby && nearby->model && !chrIsDead(nearby) &&
					nearby->actiontype != ACT_DEAD &&
					nearby->alertness > 100 &&
					chr->squadron == nearby->squadron &&
					chr->chrnum != nearby->chrnum &&
					chrGetDistanceToChr(chr, nearby->chrnum) < 3500) {
				numnearby++;
			}
		}
	}
	if (numnearby == 0) {
		score -= 2;
	} else if (numnearby == 1) {
		score--;
	}
	if (score < 3 && numnearby != 0) {
		score = 3;
	}
	*out_nearby = numnearby;
	if (out_chr_count) {
		*out_chr_count = chr_count;
	}
	if (out_source_chr) {
		*out_source_chr = source_chr;
	}
	if (out_checked_chrs) {
		*out_checked_chrs = checked_chrs;
	}
	if (out_score) {
		*out_score = score;
	}
	return 1;
}

s32 scenarioSourceAiGraphExecuteIfSafety2LessThan(struct chrdata *chr,
	s32 threshold, s32 label)
{
	s32 required;
	s32 nearby;
	s32 score;
	s32 chr_count = 0;
	s32 source_chr = -1;
	s32 checked_chrs = 0;
	s32 branch_taken;

	required = s_aiGraphRequireSafetyDetectionNode("if_safety2_less_than",
		s_ActiveScenarioGraphs.level_ai_if_safety2_less_than_node_count);
	if (required <= 0) {
		return required < 0 ? 1 : 0;
	}
	if (!s_aiGraphSafety2Score(chr, &nearby, &chr_count, &source_chr,
			&checked_chrs, &score)) {
		return 1;
	}
	branch_taken = chr && score < threshold;
	s_aiGraphApplyBranch(branch_taken, label, 4);
	if (!s_ActiveScenarioGraphs.ai_condition_if_safety2_less_than_logged) {
		sysLogPrintf(LOG_NOTE,
			"SCENARIO.GRAPH: AI condition if_safety2_less_than chr_rows=%d source_chr=%d checked=%d threshold=%d score=%d nearby=%d label=%d branch=%d source=%s backend=graph.ai.condition.safety_detection+ai/ailists.json",
			chr_count, source_chr, checked_chrs, threshold, score, nearby,
			label, branch_taken,
			s_ActiveScenarioGraphs.ai_lists_path);
		s_ActiveScenarioGraphs.ai_condition_if_safety2_less_than_logged = 1;
	}
	return 1;
}

