s32 scenarioSourceAiGraphExecuteSetMaxDamage(struct chrdata *basechr,
	struct chopperobj *hovercar, s32 chrnum, f32 maxdamage)
{
	struct chrdata *chr;
	s32 applied;
	s32 chr_count = 0;
	s32 target_chrnum = -1;
	s32 vehicle_count = 0;
	s32 source_vehicle_type = -1;

	if (!s_ActiveScenarioGraphs.level_graph_active) {
		return 0;
	}
	if (s_ActiveScenarioGraphs.level_ai_set_max_damage_node_count != 1) {
		return s_aiGraphRuntimeFailure("set_max_damage",
			"missing scenario.ai.action.set_max_damage node");
	}
	if (!basechr && !hovercar) {
		return s_aiGraphRuntimeFailure("set_max_damage",
			"missing base chr or hovercar");
	}
	if (!s_ActiveScenarioGraphs.ai_lists_path[0]) {
		return s_aiGraphRuntimeFailure("set_max_damage",
			"missing ai/ailists.json source");
	}
	applied = 0;
	if (hovercar) {
		if (!s_aiGraphRequireRuntimeVehicleObjectPointer(
				"set_max_damage", &hovercar->base,
				OBJTYPE_CHOPPER, OBJTYPE_HOVERCAR, &vehicle_count,
				&source_vehicle_type)) {
			return 1;
		}
		chopperSetMaxDamage(hovercar, maxdamage);
		applied = 1;
	} else {
		if (!s_aiGraphRequireRuntimeCharacterRefFromBase(
				"set_max_damage", basechr, chrnum,
				&chr_count, &chr)) {
			return 0;
		}
		target_chrnum = chr ? chr->chrnum : -1;
		if (chr && chr->prop && !chrIsDead(chr) &&
				chr->actiontype != ACT_DEAD &&
				chr->actiontype != ACT_DIE &&
				chr->actiontype != ACT_DRUGGEDKO &&
				chr->actiontype != ACT_DRUGGEDDROP &&
				chr->actiontype != ACT_DRUGGEDCOMINGUP) {
			chrSetMaxDamage(chr, maxdamage);
			applied = 1;
		}
	}
	if (!s_ActiveScenarioGraphs.ai_action_set_max_damage_logged) {
		sysLogPrintf(LOG_NOTE,
			"SCENARIO.GRAPH: AI action set_max_damage chr=%d chr_rows=%d target_chr=%d vehicle_rows=%d source_vehicle_type=%d value=%.3f applied=%d source=%s objects=%s backend=graph.ai.action.set_max_damage+ai/ailists.json+objects.json",
			chrnum, chr_count, target_chrnum, vehicle_count,
			source_vehicle_type, maxdamage, applied,
			s_ActiveScenarioGraphs.ai_lists_path,
			s_ActiveScenarioGraphs.objects_path);
		s_ActiveScenarioGraphs.ai_action_set_max_damage_logged = 1;
	}
	return 1;
}

