static u32 *s_aiGraphObjectFlagBank(struct defaultobj *obj, s32 bank)
{
	if (!obj) {
		return NULL;
	}
	if (bank == 1) {
		return &obj->flags;
	}
	if (bank == 2) {
		return &obj->flags2;
	}
	if (bank == 3) {
		return &obj->flags3;
	}
	return NULL;
}

