s32 scenarioSourceAiGraphExecuteShowCutsceneChrs(s32 show)
{
	s32 i;
	s32 slot_count;
	s32 chr_count = 0;
	s32 checked_chrs = 0;
	s32 applied = 0;
	s32 source_chr = -1;
	struct chrdata *chr;

	if (!s_ActiveScenarioGraphs.level_graph_active) {
		return 0;
	}
	if (s_ActiveScenarioGraphs.level_ai_show_cutscene_chrs_node_count != 1) {
		return s_aiGraphRuntimeFailure("show_cutscene_chrs",
			"missing scenario.ai.action.show_cutscene_chrs node");
	}
	if (!s_ActiveScenarioGraphs.ai_lists_path[0]) {
		return s_aiGraphRuntimeFailure("show_cutscene_chrs",
			"missing ai/ailists.json source");
	}
	if (!s_aiGraphCountRuntimeSetupChrRowsFromSource(
			"show_cutscene_chrs", &chr_count)) {
		return 1;
	}

	slot_count = chrsGetNumSlots();
	if (slot_count > 0) {
		struct chrdata *checked_chr_slots[slot_count];

		if (show) {
			for (i = slot_count - 1; i >= 0; i--) {
				chr = &g_ChrSlots[i];
				if (chr->chrnum >= 0 && chr->prop &&
						(chr->hidden2 &
							CHRH2FLAG_HIDDENFORCUTSCENE)) {
					if (!s_aiGraphRequireRuntimeCharacterPointer(
							"show_cutscene_chrs", chr,
							&chr_count, &source_chr)) {
						return 1;
					}
					checked_chr_slots[checked_chrs++] = chr;
				}
			}
			for (i = 0; i < checked_chrs; i++) {
				chr = checked_chr_slots[i];
				chr->hidden2 &=
					~CHRH2FLAG_HIDDENFORCUTSCENE;
				chr->chrflags &= ~CHRCFLAG_HIDDEN;
				applied++;
			}
		} else {
			for (i = slot_count - 1; i >= 0; i--) {
				chr = &g_ChrSlots[i];
				if (chr->chrnum >= 0 && chr->prop &&
						(chr->chrflags &
							(CHRCFLAG_UNPLAYABLE |
								CHRCFLAG_HIDDEN)) == 0) {
					if (!s_aiGraphRequireRuntimeCharacterPointer(
							"show_cutscene_chrs", chr,
							&chr_count, &source_chr)) {
						return 1;
					}
					checked_chr_slots[checked_chrs++] = chr;
				}
			}
			for (i = 0; i < checked_chrs; i++) {
				chr = checked_chr_slots[i];
				chr->hidden2 |= CHRH2FLAG_HIDDENFORCUTSCENE;
				chr->chrflags |= CHRCFLAG_HIDDEN;
				applied++;
			}
		}
	}
	if (!s_ActiveScenarioGraphs.ai_action_show_cutscene_chrs_logged) {
		sysLogPrintf(LOG_NOTE,
			"SCENARIO.GRAPH: AI action show_cutscene_chrs show=%d chr_rows=%d checked_chrs=%d applied=%d source=%s backend=graph.ai.action.cutscene_visibility+ai/ailists.json",
			show ? 1 : 0, chr_count, checked_chrs, applied,
			s_ActiveScenarioGraphs.ai_lists_path);
		s_ActiveScenarioGraphs.ai_action_show_cutscene_chrs_logged = 1;
	}
	return 1;
}

s32 scenarioSourceAiGraphExecuteConfigureEnvironment(s32 roomnum,
	s32 command, s32 value)
{
	s32 i;
	s32 room_count = 0;
	s32 room_available = 0;

	if (!s_ActiveScenarioGraphs.level_graph_active) {
		return 0;
	}
	if (s_ActiveScenarioGraphs.level_ai_configure_environment_node_count != 1) {
		return s_aiGraphRuntimeFailure("configure_environment",
			"missing scenario.ai.action.configure_environment node");
	}
	if (!s_ActiveScenarioGraphs.ai_lists_path[0]) {
		return s_aiGraphRuntimeFailure("configure_environment",
			"missing ai/ailists.json source");
	}

	switch (command) {
	case AIENVCMD_00:
		var8006ae18 = value;
		break;
	case AIENVCMD_01:
		var8006ae1c = value;
		break;
	case AIENVCMD_02:
		var8006ae20 = value;
		break;
	case AIENVCMD_03:
		var8006ae24 = value;
		break;
	case AIENVCMD_04:
		var8006ae28 = value;
		break;
	case AIENVCMD_ROOM_SETAMBIENT:
		if (!s_aiGraphResolveRuntimeSceneRoom("configure_environment",
				roomnum, &room_count, &room_available)) {
			return 1;
		}
		if (room_available) {
			g_Rooms[roomnum].flags &= ~ROOMFLAG_PLAYAMBIENTTRACK;
			if (value) {
				g_Rooms[roomnum].flags |= ROOMFLAG_PLAYAMBIENTTRACK;
			}
		}
		break;
	case AIENVCMD_ROOM_SETOUTDOORS:
		if (!s_aiGraphResolveRuntimeSceneRoom("configure_environment",
				roomnum, &room_count, &room_available)) {
			return 1;
		}
		if (room_available) {
			g_Rooms[roomnum].flags &= ~ROOMFLAG_OUTDOORS;
			if (value) {
				g_Rooms[roomnum].flags |= ROOMFLAG_OUTDOORS;
			}
		}
		break;
	case AIENVCMD_07:
		if (!s_aiGraphResolveRuntimeSceneRoom("configure_environment",
				roomnum, &room_count, &room_available)) {
			return 1;
		}
		if (room_available) {
			g_Rooms[roomnum].unk4e_04 = value;
		}
		break;
	case AIENVCMD_08:
		if (!s_aiGraphResolveRuntimeSceneRoom("configure_environment",
				roomnum, &room_count, &room_available)) {
			return 1;
		}
		if (room_available) {
			g_Rooms[roomnum].unk4d = value;
		}
		break;
	case AIENVCMD_SETAMBIENT:
		if (!s_aiGraphRequireRuntimeSceneRooms("configure_environment",
				&room_count)) {
			return 1;
		}
		for (i = 1; i < g_Vars.roomcount; i++) {
			if (value) {
				g_Rooms[i].flags |= ROOMFLAG_PLAYAMBIENTTRACK;
			} else {
				g_Rooms[i].flags &= ~ROOMFLAG_PLAYAMBIENTTRACK;
			}
		}
		break;
	case AIENVCMD_PLAYNOSEDIVE:
		sndPlayNosedive(value);
		break;
	case AIENVCMD_TICKMUSICQUEUE:
		musicTickEvents();
		break;
	case AIENVCMD_ROOM_SETFAULTYLIGHTS:
		if (!s_aiGraphResolveRuntimeSceneRoom("configure_environment",
				roomnum, &room_count, &room_available)) {
			return 1;
		}
		if (room_available) {
			roomSetLightsFaulty(roomnum, value);
		}
		break;
	case AIENVCMD_STOPNOSEDIVE:
		sndStopNosedive();
		break;
	case AIENVCMD_PLAYUFOHUM:
		sndPlayUfo(value);
		break;
	case AIENVCMD_STOPUFOHUM:
		sndStopUfo();
		break;
	}

	if (!s_ActiveScenarioGraphs.ai_action_configure_environment_logged) {
		sysLogPrintf(LOG_NOTE,
			"SCENARIO.GRAPH: AI action configure_environment room=%d room_rows=%d command=0x%02x value=%d source=%s backend=graph.ai.action.environment+ai/ailists.json+scenario.ini+scene.glb",
			roomnum, room_count, (u32)(command & 0xff), value,
			s_ActiveScenarioGraphs.ai_lists_path);
		s_ActiveScenarioGraphs.ai_action_configure_environment_logged = 1;
	}
	return 1;
}

s32 scenarioSourceAiGraphExecuteIfDistanceToTarget2(struct chrdata *chr,
	f32 distance, s32 greater_than, s32 label)
{
	f32 actual;
	s32 matched;
	s32 chr_count = 0;
	s32 source_chr = -1;
	const char *action;

	if (!s_ActiveScenarioGraphs.level_graph_active) {
		return 0;
	}

	action = greater_than
		? "if_distance_to_target2_greater_than"
		: "if_distance_to_target2_less_than";

	if (greater_than) {
		if (s_ActiveScenarioGraphs
				.level_ai_if_distance_to_target2_greater_than_node_count != 1) {
			return s_aiGraphRuntimeFailure(action,
				"missing scenario.ai.condition.if_distance_to_target2_greater_than node");
		}
	} else if (s_ActiveScenarioGraphs
			.level_ai_if_distance_to_target2_less_than_node_count != 1) {
		return s_aiGraphRuntimeFailure(action,
			"missing scenario.ai.condition.if_distance_to_target2_less_than node");
	}
	if (!s_ActiveScenarioGraphs.ai_lists_path[0]) {
		return s_aiGraphRuntimeFailure(action,
			"missing ai/ailists.json source");
	}
	if (!s_aiGraphRequireRuntimeCharacterPointer(action, chr,
			&chr_count, &source_chr)) {
		return 1;
	}

	actual = chrGetDistanceToTarget2(chr);
	matched = greater_than ? actual > distance : actual < distance;

	if (matched) {
		g_Vars.aioffset = chraiGoToLabel(g_Vars.ailist,
			g_Vars.aioffset, label);
	} else {
		g_Vars.aioffset += 5;
	}

	if (!s_ActiveScenarioGraphs.ai_action_if_distance_to_target2_logged) {
		sysLogPrintf(LOG_NOTE,
			"SCENARIO.GRAPH: AI condition %s chr_rows=%d source_chr=%d actual=%.2f threshold=%.2f label=%d source=%s backend=graph.ai.condition.target_distance+ai/ailists.json",
			action, chr_count, source_chr, (double)actual,
			(double)distance, label,
			s_ActiveScenarioGraphs.ai_lists_path);
		s_ActiveScenarioGraphs.ai_action_if_distance_to_target2_logged = 1;
	}
	return 1;
}

static s32 s_aiAudioGraphReady(const char *action, s32 node_count,
	const char *missing_reason)
{
	if (!s_ActiveScenarioGraphs.level_graph_active) {
		return 0;
	}
	if (node_count != 1) {
		return s_aiGraphRuntimeFailure(action, missing_reason);
	}
	if (!s_ActiveScenarioGraphs.ai_lists_path[0]) {
		return s_aiGraphRuntimeFailure(action,
			"missing ai/ailists.json source");
	}
	return 1;
}

static s32 s_voiceLanguageMatchesActive(const char *language)
{
	s32 source_locale;
	s32 active_locale;
	if (!language || !language[0]) return 1;
	source_locale = voiceLocaleIndex(language);
	active_locale = voiceLocaleIndex(voiceLocaleActiveTag());
	return source_locale >= 0 && source_locale == active_locale;
}

static const char *s_voiceSourceSubtitle(const char *audio_catalog_id,
	char *out_text, size_t out_text_size)
{
	catalog_audio_result_t audio;

	if (!audio_catalog_id || !out_text || out_text_size == 0
			|| strncmp(audio_catalog_id, "file:", 5) == 0
			|| !catalogResolveAudio(audio_catalog_id, &audio)
			|| audio.category != AUDIO_CAT_VOICE
			|| !audio.voice_transcript || !audio.voice_transcript[0]
			|| !s_voiceLanguageMatchesActive(audio.voice_language)) {
		return NULL;
	}
	if (audio.voice_actor && audio.voice_actor[0]) {
		snprintf(out_text, out_text_size, "%s: %s",
			audio.voice_actor, audio.voice_transcript);
	} else {
		snprintf(out_text, out_text_size, "%s", audio.voice_transcript);
	}
	out_text[out_text_size - 1] = '\0';
	return out_text;
}

s32 scenarioSourceAiGraphExecuteSpeak(struct chrdata *basechr, s32 chrnum,
	s16 text_id, s16 audio_id, s8 channel, s32 subtitle_timer)
{
	struct chrdata *chr;
	s32 prevplayernum;
	s32 playernum;
	u32 channelnum;
	char *text;
	char voice_text[640];
	const char *voice_source_text;
	const char *audio_source_id;
	char audio_source_id_buf[FS_MAXPATH + 32];
	const char *text_catalog_id;
	s32 chr_count = 0;
	s32 target_chrnum = -1;
	s32 target_selector = 0;
	s32 player_checked = 0;
	s32 ready = s_aiAudioGraphReady("speak",
		s_ActiveScenarioGraphs.level_ai_speak_node_count,
		"missing scenario.ai.action.speak node");

	if (ready != 1) {
		return ready;
	}
	audio_source_id = s_aiGraphResolveSpeechAudioSourceId("speak", audio_id,
		"speech", audio_source_id_buf, sizeof(audio_source_id_buf));
	if (!audio_source_id) {
		return 1;
	}
	text_catalog_id = s_aiGraphResolveLangTextCatalogId("speak", text_id,
		"speech text");
	if (!text_catalog_id) {
		return 1;
	}
	if (!s_aiGraphResolveRuntimeCharacterRefOrSelector("speak", basechr,
			chrnum, &chr_count, &chr, &target_selector)) {
		return 1;
	}
	if (chr) {
		target_chrnum = chr->chrnum;
	}
	prevplayernum = g_Vars.currentplayernum;
	playernum = prevplayernum;
	text = text_id >= 0 ? langGet(text_id) : NULL;
	voice_source_text = s_voiceSourceSubtitle(audio_source_id,
		voice_text, sizeof(voice_text));
	if (voice_source_text) {
		text = (char *)voice_source_text;
	}
	if (chr && chr->prop && chr->prop->type == PROPTYPE_PLAYER) {
		playernum = playermgrGetPlayerNumByProp(chr->prop);
		if (!s_aiGraphRequireRuntimePlayerSlot("speak",
				playernum, NULL)) {
			return 1;
		}
		player_checked = 1;
	} else if (!s_aiGraphRequireRuntimePlayerSlot("speak",
			playernum, NULL)) {
		return 1;
	}
	setCurrentPlayerNum(playernum);
	if (text && chrnum != CHR_P1P2) {
		psStopSound(basechr->prop, PSTYPE_CHRTALK, 0xffff);
	}
	if (chrnum == CHR_P1P2) {
		channelnum = psPlayFromProp(channel, audio_id, 0, basechr->prop,
			PSTYPE_NONE, PSFLAG_FORHUDMSG);
	} else {
		channelnum = psPlayFromProp(channel, audio_id, 0, basechr->prop,
			PSTYPE_CHRTALK, PSFLAG_FORHUDMSG);
	}
	if (text && !sndIsFiltered(audio_id)) {
		hudmsgCreateAsSubtitle(text, HUDMSGTYPE_INGAMESUBTITLE,
			subtitle_timer, channelnum);
	}
	setCurrentPlayerNum(prevplayernum);
	g_Vars.aioffset += 9;
	if (!s_ActiveScenarioGraphs.ai_action_speak_logged) {
		sysLogPrintf(LOG_NOTE,
			"SCENARIO.GRAPH: AI action speak chr=%d chr_rows=%d target_chr=%d target_selector=%d player_checked=%d text_id=%s audio_id=%s voice_source=%d channel=%d source=%s backend=graph.ai.action.audio+ai/ailists.json+pdvoice+lang",
			chrnum, chr_count, target_chrnum, target_selector,
			player_checked, text_catalog_id, audio_source_id,
			voice_source_text != NULL, channel,
			s_ActiveScenarioGraphs.ai_lists_path);
		s_ActiveScenarioGraphs.ai_action_speak_logged = 1;
	}
	return 1;
}

