s32 scenarioSourceAiGraphExecuteClearInventory(void)
{
	u32 prevplayernum;
	s32 playernum;
	s32 cleared = 0;
	s32 checked_players = 0;

	if (!s_ActiveScenarioGraphs.level_graph_active) {
		return 0;
	}
	if (s_ActiveScenarioGraphs.level_ai_clear_inventory_node_count != 1) {
		return s_aiGraphRuntimeFailure("clear_inventory",
			"missing scenario.ai.action.clear_inventory node");
	}
	if (!s_ActiveScenarioGraphs.ai_lists_path[0]) {
		return s_aiGraphRuntimeFailure("clear_inventory",
			"missing ai/ailists.json source");
	}
	prevplayernum = g_Vars.currentplayernum;
	for (playernum = 0; playernum < PLAYERCOUNT(); playernum++) {
		struct player *player = NULL;
		if (!s_aiGraphRequireRuntimePlayerSlot("clear_inventory",
				playernum, &player)) {
			setCurrentPlayerNum(prevplayernum);
			return 1;
		}
		checked_players++;
		setCurrentPlayerNum(playernum);
		if (playernum == g_Vars.bondplayernum ||
				playernum == g_Vars.coopplayernum) {
			invClear();
#if VERSION >= VERSION_NTSC_1_0
			player->devicesactive = 0;
#endif
			invGiveSingleWeapon(WEAPON_UNARMED);
			bgunEquipWeapon(WEAPON_UNARMED);
			cleared++;
		}
	}
	setCurrentPlayerNum(prevplayernum);
	g_Vars.aioffset += 3;
	if (!s_ActiveScenarioGraphs.ai_action_clear_inventory_logged) {
		sysLogPrintf(LOG_NOTE,
			"SCENARIO.GRAPH: AI action clear_inventory checked_players=%d players=%d source=%s backend=graph.ai.action.character_inventory+ai/ailists.json",
			checked_players, cleared, s_ActiveScenarioGraphs.ai_lists_path);
		s_ActiveScenarioGraphs.ai_action_clear_inventory_logged = 1;
	}
	return 1;
}

