s32 scenarioSourceAiGraphExecuteIfPlayerUsingDevice(struct chrdata *basechr,
	s32 chrnum, s32 devicenum, s32 label)
{
	struct chrdata *chr;
	struct prop *prop;
	u32 prevplayernum;
	s32 chr_count = 0;
	s32 playernum = -1;
	s32 branch_taken = 0;
	s32 player_checked = 0;

	if (!s_ActiveScenarioGraphs.level_graph_active) {
		return 0;
	}
	if (s_ActiveScenarioGraphs.level_ai_if_player_using_device_node_count != 1) {
		return s_aiGraphRuntimeFailure("if_player_using_device",
			"missing scenario.ai.condition.if_player_using_device node");
	}
	if (!s_ActiveScenarioGraphs.ai_lists_path[0]) {
		return s_aiGraphRuntimeFailure("if_player_using_device",
			"missing ai/ailists.json source");
	}
	if (!s_aiGraphRequireRuntimeCharacterRefFromBase(
			"if_player_using_device", basechr, chrnum,
			&chr_count, &chr)) {
		return 1;
	}
	prop = chr ? chr->prop : NULL;
	prevplayernum = g_Vars.currentplayernum;
	if (prop && prop->type == PROPTYPE_PLAYER) {
		playernum = playermgrGetPlayerNumByProp(prop);
		if (!s_aiGraphRequireRuntimePlayerSlot("if_player_using_device",
				playernum, NULL)) {
			return 1;
		}
		player_checked = 1;
		setCurrentPlayerNum(playernum);
		branch_taken = currentPlayerGetDeviceState(devicenum) ==
			DEVICESTATE_ACTIVE;
		setCurrentPlayerNum(prevplayernum);
	}
	if (branch_taken) {
		g_Vars.aioffset = chraiGoToLabel(g_Vars.ailist,
			g_Vars.aioffset, label);
	} else {
		g_Vars.aioffset += 5;
	}
	if (!s_ActiveScenarioGraphs
			.ai_condition_if_player_using_device_logged) {
		sysLogPrintf(LOG_NOTE,
			"SCENARIO.GRAPH: AI condition if_player_using_device chr=%d chr_rows=%d target_chr=%d player=%d player_checked=%d device=%d label=%d branch=%d source=%s backend=graph.ai.condition.state_device+ai/ailists.json",
			chrnum, chr_count, chr ? chr->chrnum : -1, playernum,
			player_checked, devicenum, label, branch_taken,
			s_ActiveScenarioGraphs.ai_lists_path);
		s_ActiveScenarioGraphs
			.ai_condition_if_player_using_device_logged = 1;
	}
	return 1;
}

static void s_aiGraphPlayTeleportSound(s32 soundnum)
{
	struct sndstate *handle;
	f32 pitch = 0.4f;
#if VERSION >= VERSION_NTSC_1_0
	s32 mainpri;
	s32 audiopri;

	mainpri = osGetThreadPri(0);
	audiopri = osGetThreadPri(&g_AudioManager.thread);
	osSetThreadPri(0, audiopri + 1);
#endif
	handle = sndStart(var80095200, soundnum, NULL, -1, -1, -1, -1, -1);
	if (handle) {
		audioPostEvent(handle, AL_SNDP_PITCH_EVT, *(u32 *)&pitch);
	}
#if VERSION >= VERSION_NTSC_1_0
	osSetThreadPri(0, mainpri);
#endif
}

s32 scenarioSourceAiGraphExecuteChrBeginOrEndTeleport(struct chrdata *basechr,
	s32 chrnum, s32 pad_id)
{
	struct chrdata *chr;
	struct player *player = NULL;
	const char *sound_id = "none";
	u32 prevplayernum;
	s32 chr_count = 0;
	s32 playernum = -1;
	s32 pad_count = 0;
	s32 player_checked = 0;

	if (!s_ActiveScenarioGraphs.level_graph_active) {
		return 0;
	}
	if (s_ActiveScenarioGraphs
			.level_ai_chr_begin_or_end_teleport_node_count != 1) {
		return s_aiGraphRuntimeFailure("chr_begin_or_end_teleport",
			"missing scenario.ai.action.chr_begin_or_end_teleport node");
	}
	if (!s_ActiveScenarioGraphs.ai_lists_path[0]) {
		return s_aiGraphRuntimeFailure("chr_begin_or_end_teleport",
			"missing ai/ailists.json source");
	}
	if (!s_aiGraphRequireRuntimeCharacterRefFromBase(
			"chr_begin_or_end_teleport", basechr, chrnum,
			&chr_count, &chr)) {
		return 1;
	}
	if (pad_id != 0) {
		if (!s_ActiveScenarioGraphs.pads_path[0]) {
			return s_aiGraphRuntimeFailure("chr_begin_or_end_teleport",
				"missing pads.json source");
		}
		if (!s_aiGraphRequireRuntimePad("chr_begin_or_end_teleport",
				pad_id, &pad_count)) {
			return 1;
		}
		sound_id = s_aiGraphResolveAudioCatalogId(
			"chr_begin_or_end_teleport", SFX_RELOAD_FARSIGHT,
			"teleport start");
		if (!sound_id) {
			return 1;
		}
	}
	prevplayernum = g_Vars.currentplayernum;
	if (chr && chr->prop && chr->prop->type == PROPTYPE_PLAYER) {
		playernum = playermgrGetPlayerNumByProp(chr->prop);
	}
	if (!s_aiGraphRequireRuntimePlayerSlot("chr_begin_or_end_teleport",
			playernum, &player)) {
		return 1;
	}
	player_checked = 1;
	setCurrentPlayerNum(playernum);
	if (pad_id == 0) {
		player->teleportstate = TELEPORTSTATE_EXITING;
		player->teleporttime = 0;
	} else {
		player->teleporttime = 0;
		player->teleportstate = TELEPORTSTATE_PREENTER;
		player->teleportpad = pad_id;
		player->teleportcamerapad = 0;
		s_aiGraphPlayTeleportSound(SFX_RELOAD_FARSIGHT);
	}
	g_Vars.aioffset += 5;
	setCurrentPlayerNum(prevplayernum);
	if (!s_ActiveScenarioGraphs
			.ai_action_chr_begin_or_end_teleport_logged) {
		sysLogPrintf(LOG_NOTE,
			"SCENARIO.GRAPH: AI action chr_begin_or_end_teleport chr=%d chr_rows=%d target_chr=%d player=%d player_checked=%d pad=%d found=%d pad_rows=%d sound_id=%s source=%s pads=%s backend=graph.ai.action.teleport_cutscene_weapon+ai/ailists.json+pads.json+audio",
			chrnum, chr_count, chr ? chr->chrnum : -1, playernum,
			player_checked, pad_id, pad_id != 0, pad_count, sound_id,
			s_ActiveScenarioGraphs.ai_lists_path,
			s_ActiveScenarioGraphs.pads_path[0]
				? s_ActiveScenarioGraphs.pads_path : "(not-required)");
		s_ActiveScenarioGraphs
			.ai_action_chr_begin_or_end_teleport_logged = 1;
	}
	return 1;
}

