u8 *scenarioSourceLoadSetupForStage(const catalog_stage_result_t *stage,
	s32 prefer_mp, s32 *out_size)
{
	const asset_entry_t *scenario;
	char setup_path[FS_MAXPATH + 1];
	char objects_path[FS_MAXPATH + 1];
	char spawns_path[FS_MAXPATH + 1];
	char ai_lists_path[FS_MAXPATH + 1];
	char paths_path[FS_MAXPATH + 1];
	u32 text_size;
	char *setup_text;
	char *objects_text;
	char *spawns_text;
	char *ai_text;
	char *paths_text;
	scenario_source_setup_table_t table;
	scenario_source_spawn_table_t spawn_table;
	scenario_source_ai_table_t ai_table;
	scenario_source_path_table_t path_table;
	u8 *setup_data;
	const char *stageid;

	if (out_size) {
		*out_size = 0;
	}

	scenario = s_findScenarioForStage(stage, prefer_mp);
	if (!scenario || !s_scenarioSetupFieldsPath(scenario, setup_path,
			sizeof(setup_path))) {
		return NULL;
	}

	text_size = 0;
	setup_text = s_loadOptionalText(setup_path, &text_size);
	if (!setup_text) {
		if (assetSourceDebugIsEnabledFor(ASSET_SCENARIO)) {
			sysLogPrintf(LOG_ERROR,
				"SCENARIO.SOURCE: missing public setup.fields.json for '%s' at %s",
				scenario->id, setup_path);
		}
		return NULL;
	}

	memset(&table, 0, sizeof(table));
	memset(&spawn_table, 0, sizeof(spawn_table));
	memset(&ai_table, 0, sizeof(ai_table));
	memset(&path_table, 0, sizeof(path_table));
	if (!s_setupParseFieldsJson(setup_text, &table)) {
		sysLogPrintf(LOG_ERROR,
			"SCENARIO.SOURCE: invalid public setup.fields.json for '%s': %s",
			scenario->id, table.error[0] ? table.error : "parse failed");
		free(setup_text);
		s_setupFreeTable(&table);
		return NULL;
	}
	free(setup_text);

	objects_text = NULL;
	if (s_scenarioObjectsPath(scenario, objects_path, sizeof(objects_path))) {
		objects_text = s_loadOptionalText(objects_path, &text_size);
	}
	if (objects_text) {
		if (!s_setupApplyObjectsJson(objects_text, &table)) {
			sysLogPrintf(LOG_ERROR,
				"SCENARIO.SOURCE: invalid public objects.json for '%s': %s",
				scenario->id, table.error[0] ? table.error : "parse failed");
			free(objects_text);
			s_setupFreeTable(&table);
			s_freePathTable(&path_table);
			s_aiFreeTable(&ai_table);
			return NULL;
		}
		free(objects_text);
	}

	spawns_text = NULL;
	if (s_scenarioSpawnsPath(scenario, spawns_path, sizeof(spawns_path))) {
		spawns_text = s_loadOptionalText(spawns_path, &text_size);
	}
	if (!spawns_text) {
		sysLogPrintf(LOG_ERROR,
			"SCENARIO.SOURCE: missing public spawns.json for '%s'",
			scenario->id);
		s_setupFreeTable(&table);
		s_spawnFreeTable(&spawn_table);
		s_freePathTable(&path_table);
		s_aiFreeTable(&ai_table);
		return NULL;
	}
	if (!s_loadSpawnSourceRows(spawns_text, &spawn_table)) {
		sysLogPrintf(LOG_ERROR,
			"SCENARIO.SOURCE: invalid public spawns.json for '%s': %s",
			scenario->id, spawn_table.error[0] ? spawn_table.error : "parse failed");
		free(spawns_text);
		s_setupFreeTable(&table);
		s_spawnFreeTable(&spawn_table);
		s_freePathTable(&path_table);
		s_aiFreeTable(&ai_table);
		return NULL;
	}
	free(spawns_text);

	paths_text = NULL;
	if (s_scenarioPathsPath(scenario, paths_path, sizeof(paths_path))) {
		paths_text = s_loadOptionalText(paths_path, &text_size);
	}
	if (!paths_text) {
		sysLogPrintf(LOG_ERROR,
			"SCENARIO.SOURCE: missing public navigation/paths.json for '%s'",
			scenario->id);
		s_setupFreeTable(&table);
		s_spawnFreeTable(&spawn_table);
		s_freePathTable(&path_table);
		s_aiFreeTable(&ai_table);
		return NULL;
	}
	if (!s_loadPathSourceRows(paths_text, &path_table)) {
		sysLogPrintf(LOG_ERROR,
			"SCENARIO.SOURCE: invalid public navigation/paths.json for '%s': %s",
			scenario->id, path_table.error[0]
				? path_table.error : "parse failed");
		free(paths_text);
		s_setupFreeTable(&table);
		s_spawnFreeTable(&spawn_table);
		s_freePathTable(&path_table);
		s_aiFreeTable(&ai_table);
		return NULL;
	}
	free(paths_text);

	ai_text = NULL;
	if (s_scenarioAiListsPath(scenario, ai_lists_path, sizeof(ai_lists_path))) {
		ai_text = s_loadOptionalText(ai_lists_path, &text_size);
	}
	if (!ai_text) {
		sysLogPrintf(LOG_ERROR,
			"SCENARIO.SOURCE: missing public ai/ailists.json for '%s'",
			scenario->id);
		s_setupFreeTable(&table);
		s_spawnFreeTable(&spawn_table);
		s_freePathTable(&path_table);
		s_aiFreeTable(&ai_table);
		return NULL;
	}
	if (!s_loadAiListSourceJson(ai_text, &ai_table)) {
		sysLogPrintf(LOG_ERROR,
			"SCENARIO.SOURCE: invalid public ai/ailists.json for '%s': %s",
			scenario->id, ai_table.error[0] ? ai_table.error : "parse failed");
		free(ai_text);
		s_setupFreeTable(&table);
		s_spawnFreeTable(&spawn_table);
		s_freePathTable(&path_table);
		s_aiFreeTable(&ai_table);
		return NULL;
	}
	free(ai_text);

	if (table.count > 1) {
		qsort(table.records, (size_t)table.count, sizeof(table.records[0]),
			s_setupCompareRecords);
	}
	if (!s_setupCollectBehaviorLinkSource(scenario, setup_path, &table)) {
		s_setupFreeTable(&table);
		s_spawnFreeTable(&spawn_table);
		s_freePathTable(&path_table);
		s_aiFreeTable(&ai_table);
		return NULL;
	}

	setup_data = s_setupBuildStageBlock(&table, &spawn_table, &ai_table,
		&path_table, scenario->id, out_size);
	stageid = (stage && stage->entry && stage->entry->id[0])
		? stage->entry->id : "?";
	if (setup_data) {
		s_activeGraphSetSourceSetupChrRefs(&table);
		sysLogPrintf(LOG_NOTE,
			"SCENARIO.SOURCE: compiled setup.fields.json '%s', spawns.json '%s', navigation/paths.json '%s', and ai/ailists.json '%s' for stage '%s' as %d setup records, %d spawns, %d paths, %d AI lists (%d bytes) path_flags=circular:%d,flying:%d",
			setup_path, spawns_path, paths_path, ai_lists_path, stageid,
			table.count, spawn_table.count, path_table.count, ai_table.count,
			out_size ? *out_size : 0,
			s_countPathRowsWithFlag(&path_table, PATHFLAG_CIRCULAR),
			s_countPathRowsWithFlag(&path_table, PATHFLAG_FLYING));
	} else {
		s_ActiveScenarioGraphs.source_setup_chr_count = 0;
		s_ActiveScenarioGraphs.source_setup_chr_ref_count = 0;
		s_ActiveScenarioGraphs.source_setup_record_count = 0;
		s_ActiveScenarioGraphs.source_setup_record_ref_count = 0;
	}

	s_setupFreeTable(&table);
	s_spawnFreeTable(&spawn_table);
	s_freePathTable(&path_table);
	s_aiFreeTable(&ai_table);
	return setup_data;
}

static u32 s_sourceTileStride(void)
{
	return (u32)offsetof(struct geotilef, vertices)
		+ 3u * (u32)sizeof(struct coord);
}

static s32 s_portalRowsMaxRoom(const scenario_source_portal_row_t *rows,
	s32 row_count)
{
	s32 max_room = -1;

	for (s32 i = 0; rows && i < row_count; i++) {
		if (rows[i].room1 > max_room) {
			max_room = rows[i].room1;
		}
		if (rows[i].room2 > max_room) {
			max_room = rows[i].room2;
		}
	}

	return max_room;
}

s32 scenarioSourceResolveRoomCountForStage(
	const catalog_stage_result_t *stage, s32 prefer_mp,
	s32 mesh_max_room, s32 *out_room_count)
{
	const asset_entry_t *scenario;
	char portals_path[FS_MAXPATH + 1];
	u32 text_size = 0;
	char *text;
	scenario_source_portal_row_t *rows;
	s32 row_count = 0;
	s32 portal_max_room;
	s32 resolved_count = 0;
	scenario_room_domain_result_t result;

	if (out_room_count) {
		*out_room_count = 0;
	}
	if (!out_room_count) {
		return 0;
	}

	scenario = s_findScenarioForStage(stage, prefer_mp);
	if (!scenario || !scenario->id[0]
			|| !catalogLoadStageAsset(ASSET_SCENARIO, scenario->id)
			|| !s_scenarioPortalsPath(scenario, portals_path,
				sizeof(portals_path))) {
		return 0;
	}

	text = s_loadOptionalText(portals_path, &text_size);
	if (!text) {
		sysLogPrintf(LOG_ERROR,
			"SCENARIO.SOURCE: cannot resolve room domain for '%s': missing public portals source %s",
			scenario->id, portals_path);
		return 0;
	}

	rows = s_parsePortalsJson(text, &row_count);
	free(text);
	if (!rows) {
		sysLogPrintf(LOG_ERROR,
			"SCENARIO.SOURCE: cannot resolve room domain for '%s': invalid public portals source %s",
			scenario->id, portals_path);
		return 0;
	}

	portal_max_room = s_portalRowsMaxRoom(rows, row_count);
	free(rows);
	result = scenarioRoomDomainResolve(
		scenario->ext.scenario.source_room_count,
		mesh_max_room, portal_max_room, &resolved_count);
	if (result != SCENARIO_ROOM_DOMAIN_OK) {
		sysLogPrintf(LOG_ERROR,
			"SCENARIO.SOURCE: invalid room domain '%s' declared=%d mesh_max=%d portal_max=%d reason=%s",
			scenario->id, scenario->ext.scenario.source_room_count,
			mesh_max_room, portal_max_room,
			scenarioRoomDomainResultName(result));
		return 0;
	}

	*out_room_count = resolved_count;
	sysLogPrintf(LOG_NOTE,
		"SCENARIO.SOURCE: resolved room domain '%s' rooms=%d declared=%d mesh_max=%d portal_max=%d source=catalog-metadata+scene.glb+portals.json",
		scenario->id, resolved_count,
		scenario->ext.scenario.source_room_count,
		mesh_max_room, portal_max_room);
	return 1;
}

static void s_sourceTileSetBounds(struct geotilef *tile)
{
	if (!tile) {
		return;
	}

	for (s32 axis = 0; axis < 3; axis++) {
		s32 min_index = 0;
		s32 max_index = 0;
		for (s32 i = 1; i < 3; i++) {
			if (tile->vertices[i].f[axis] <
					tile->vertices[min_index].f[axis]) {
				min_index = i;
			}
			if (tile->vertices[i].f[axis] >
					tile->vertices[max_index].f[axis]) {
				max_index = i;
			}
		}
		tile->min[axis] = (u8)min_index;
		tile->max[axis] = (u8)max_index;
	}
}

u8 *scenarioSourceLoadTilesForStage(const catalog_stage_result_t *stage,
	s32 prefer_mp, s32 *out_size, s32 *out_rooms, s32 *out_tiles)
{
	const asset_entry_t *scenario;
	struct colmesh *mesh;
	s32 max_room = 0;
	s32 room_count = 0;
	s32 source_tiles = 0;
	u32 header_size;
	u32 tile_stride = s_sourceTileStride();
	u32 total_size;
	u8 *data;
	u32 *u32data;
	u32 *rooms;
	u32 cursor;
	const char *stageid;
	const char *source_path;

	if (out_size) {
		*out_size = 0;
	}
	if (out_rooms) {
		*out_rooms = 0;
	}
	if (out_tiles) {
		*out_tiles = 0;
	}

	scenario = s_findScenarioForStage(stage, prefer_mp);
	if (!scenario || !scenario->id[0]) {
		return NULL;
	}

	if (!catalogLoadStageAsset(ASSET_SCENARIO, scenario->id)) {
		if (assetSourceDebugIsEnabledFor(ASSET_SCENARIO)) {
			sysLogPrintf(LOG_ERROR,
				"SCENARIO.SOURCE: failed to activate scene source for tiles '%s'",
				scenario->id);
		}
		return NULL;
	}

	mesh = catalogGetLoadedColmesh(scenario->id);
	if (!mesh || mesh->numtris <= 0) {
		if (assetSourceDebugIsEnabledFor(ASSET_SCENARIO)) {
			sysLogPrintf(LOG_ERROR,
				"SCENARIO.SOURCE: no scene colmesh available for tile cache '%s'",
				scenario->id);
		}
		return NULL;
	}

	for (s32 i = 0; i < mesh->numtris; i++) {
		s32 room = mesh->tris[i].roomnum;
		if (room > 0) {
			if (room > max_room) {
				max_room = room;
			}
			source_tiles++;
		}
	}

	if (max_room <= 0 || source_tiles <= 0) {
		if (assetSourceDebugIsEnabledFor(ASSET_SCENARIO)) {
			sysLogPrintf(LOG_ERROR,
				"SCENARIO.SOURCE: scene source '%s' has no room-tagged triangles for tile cache",
				scenario->id);
		}
		return NULL;
	}
	if (!scenarioSourceResolveRoomCountForStage(stage, prefer_mp,
			max_room, &room_count)) {
		return NULL;
	}

	header_size = (u32)(room_count + 2) * (u32)sizeof(u32);
	if (source_tiles > 0
			&& (u32)source_tiles > (0xffffffffu - header_size) / tile_stride) {
		sysLogPrintf(LOG_ERROR,
			"SCENARIO.SOURCE: tile cache too large for '%s' tiles=%d",
			scenario->id, source_tiles);
		return NULL;
	}

	total_size = header_size + (u32)source_tiles * tile_stride;
	data = mempAlloc(total_size, MEMPOOL_STAGE);
	if (!data) {
		sysLogPrintf(LOG_ERROR,
			"SCENARIO.SOURCE: tile cache allocation failed for '%s' bytes=%u",
			scenario->id, (unsigned)total_size);
		return NULL;
	}
	memset(data, 0, total_size);

	u32data = (u32 *)data;
	*u32data = (u32)room_count;
	rooms = u32data + 1;
	cursor = header_size;

	for (s32 room = 0; room < room_count; room++) {
		rooms[room] = cursor;
		for (s32 i = 0; i < mesh->numtris; i++) {
			const struct meshtri *src = &mesh->tris[i];
			struct geotilef *tile;
			if (src->roomnum != room) {
				continue;
			}
			tile = (struct geotilef *)(data + cursor);
			tile->header.type = GEOTYPE_TILE_F;
			tile->header.numvertices = 3;
			/* B-943: carry the authoritative GEOFLAGs + floortype/floorcol from
			 * the colmesh (loaded from collision.flags.json). Previously flags
			 * came only from classifyTriFlags (FLOOR1/FLOOR2/WALL) and
			 * floortype/floorcol were hardcoded 0, so extracted stages lost
			 * DIE death-floors, LADDERs, footstep materials, and AI sight/shoot
			 * blocking. */
			tile->header.flags = src->flags;
			tile->floortype = src->floortype;
			tile->floorcol = src->floorcol;
			tile->vertices[0] = src->v0;
			tile->vertices[1] = src->v1;
			tile->vertices[2] = src->v2;
			s_sourceTileSetBounds(tile);
			cursor += tile_stride;
		}
	}
	rooms[room_count] = cursor;

	stageid = (stage && stage->entry && stage->entry->id[0])
		? stage->entry->id : "?";
	source_path = scenario->ext.scenario.collision_file[0]
		? scenario->ext.scenario.collision_file
		: scenario->ext.scenario.scene_file;
	sysLogPrintf(LOG_NOTE,
		"SCENARIO.SOURCE: compiled scene tiles '%s' for stage '%s' as %d rooms, %d tiles (%u bytes) source=%s",
		scenario->id, stageid, room_count, source_tiles,
		(unsigned)cursor,
		source_path && source_path[0] ? source_path : "(none)");

	/* B-943 round-trip diagnostic: prove the runtime tiles now carry the real
	 * GEOFLAGs (not just the 3-bit FLOOR1/FLOOR2/WALL normal reconstruction)
	 * and non-zero floortypes. Logged once per scenario id per process. */
	{
		static char s_b943LoggedScenario[CATALOG_ID_LEN];
		if (strncmp(s_b943LoggedScenario, scenario->id,
				sizeof(s_b943LoggedScenario)) != 0) {
			u32 flags_or = 0;
			u32 advanced_tiles = 0;   /* tiles with bits beyond FLOOR1/2/WALL */
			u32 floortype_tiles = 0;  /* tiles with a non-zero floortype */
			s32 shown = 0;
			for (s32 ri = 0; ri < room_count; ri++) {
				u32 a = rooms[ri];
				u32 b = rooms[ri + 1];
				while (a + tile_stride <= b) {
					struct geotilef *t = (struct geotilef *)(data + a);
					u16 f = t->header.flags;
					flags_or |= f;
					if (f & ~(u16)0x0007) advanced_tiles++;
					if (t->floortype) floortype_tiles++;
					if (shown < 8 && ((f & ~(u16)0x0007) || t->floortype)) {
						sysLogPrintf(LOG_NOTE,
							"SCENARIO.SOURCE: B-943 tile room=%d flags=0x%04x floortype=%u floorcol=%u",
							ri, (unsigned)f, (unsigned)t->floortype,
							(unsigned)t->floorcol);
						shown++;
					}
					a += tile_stride;
				}
			}
			sysLogPrintf(LOG_NOTE,
				"SCENARIO.SOURCE: B-943 collision-flags summary '%s' tiles=%d flags_union=0x%04x advanced_flag_tiles=%u floortype_tiles=%u",
				scenario->id, source_tiles, (unsigned)flags_or,
				(unsigned)advanced_tiles, (unsigned)floortype_tiles);
			strncpy(s_b943LoggedScenario, scenario->id,
				sizeof(s_b943LoggedScenario) - 1);
			s_b943LoggedScenario[sizeof(s_b943LoggedScenario) - 1] = '\0';
		}
	}

	if (out_size) {
		*out_size = (s32)cursor;
	}
	if (out_rooms) {
		*out_rooms = room_count;
	}
	if (out_tiles) {
		*out_tiles = source_tiles;
	}
	return data;
}

struct bgportal *scenarioSourceLoadPortalsForStage(
	const catalog_stage_result_t *stage, s32 prefer_mp, s32 room_count,
	s32 *out_count)
{
	const asset_entry_t *scenario;
	char portals_path[FS_MAXPATH + 1];
	u32 text_size;
	char *text;
	scenario_source_portal_row_t *rows;
	s32 row_count;
	size_t total_size;
	u8 *data;
	struct bgportal *portals;
	size_t cursor;
	const char *stageid;

	if (out_count) {
		*out_count = 0;
	}

	scenario = s_findScenarioForStage(stage, prefer_mp);
	if (!scenario || !scenario->id[0] ||
			!s_scenarioPortalsPath(scenario, portals_path,
				sizeof(portals_path))) {
		return NULL;
	}

	text = s_loadOptionalText(portals_path, &text_size);
	if (!text) {
		if (assetSourceDebugIsEnabledFor(ASSET_SCENARIO)) {
			sysLogPrintf(LOG_ERROR,
				"SCENARIO.SOURCE: missing public portals.json for '%s' at %s",
				scenario->id, portals_path);
		}
		return NULL;
	}

	rows = s_parsePortalsJson(text, &row_count);
	free(text);
	if (!rows) {
		free(rows);
		if (assetSourceDebugIsEnabledFor(ASSET_SCENARIO)) {
			sysLogPrintf(LOG_ERROR,
				"SCENARIO.SOURCE: no usable portal rows in public source '%s'",
				portals_path);
		}
		return NULL;
	}
	for (s32 i = 0; i < row_count; i++) {
		if (rows[i].room1 <= 0 || rows[i].room2 <= 0
				|| rows[i].room1 == rows[i].room2
				|| !scenarioRoomDomainContains(room_count, rows[i].room1)
				|| !scenarioRoomDomainContains(room_count, rows[i].room2)) {
			sysLogPrintf(LOG_ERROR,
				"SCENARIO.SOURCE: portal row %d for '%s' exceeds room domain rooms=%d room1=%d room2=%d",
				i, scenario->id, room_count,
				rows[i].room1, rows[i].room2);
			free(rows);
			return NULL;
		}
	}

	total_size = (size_t)(row_count + 1) * sizeof(struct bgportal);
	for (s32 i = 0; i < row_count; i++) {
		total_size += offsetof(struct portalvertices, vertices) +
			(size_t)rows[i].vertex_count * sizeof(struct coord);
	}
	if (total_size > 0xffffu) {
		sysLogPrintf(LOG_ERROR,
			"SCENARIO.SOURCE: portal table too large for '%s' portals=%d bytes=%u",
			scenario->id, row_count, (unsigned)total_size);
		free(rows);
		return NULL;
	}

	data = mempAlloc(ALIGN16((u32)total_size), MEMPOOL_STAGE);
	if (!data) {
		sysLogPrintf(LOG_ERROR,
			"SCENARIO.SOURCE: portal table allocation failed for '%s' bytes=%u",
			scenario->id, (unsigned)total_size);
		free(rows);
		return NULL;
	}
	memset(data, 0, ALIGN16((u32)total_size));
	portals = (struct bgportal *)data;
	cursor = (size_t)(row_count + 1) * sizeof(struct bgportal);

	for (s32 i = 0; i < row_count; i++) {
		struct portalvertices *verts;
		size_t block_size = offsetof(struct portalvertices, vertices) +
			(size_t)rows[i].vertex_count * sizeof(struct coord);
		portals[i].verticesoffset = (u16)cursor;
		portals[i].roomnum1 = (s16)rows[i].room1;
		portals[i].roomnum2 = (s16)rows[i].room2;
		portals[i].flags = (u8)(rows[i].flags & 0xffu);
		verts = (struct portalvertices *)(data + cursor);
		verts->count = (u8)rows[i].vertex_count;
		memcpy(verts->vertices, rows[i].vertices,
			(size_t)rows[i].vertex_count * sizeof(struct coord));
		cursor += block_size;
	}

	stageid = (stage && stage->entry && stage->entry->id[0])
		? stage->entry->id : "?";
	sysLogPrintf(LOG_NOTE,
		"SCENARIO.SOURCE: compiled portals.json '%s' for stage '%s' as %d portals across %d rooms (%u bytes)",
		portals_path, stageid, row_count, room_count, (unsigned)total_size);

	if (out_count) {
		*out_count = row_count;
	}
	free(rows);
	return portals;
}

u8 *scenarioSourceLoadPadsForStage(const catalog_stage_result_t *stage,
	s32 prefer_mp, s32 *out_size)
{
	const asset_entry_t *scenario;
	char pads_path[FS_MAXPATH + 1];
	u32 text_size;
	char *text;
	scenario_source_pad_row_t *rows;
	s32 row_count;
	scenario_source_navigation_t nav;
	u8 *padfile;
	s32 padfile_size;
	s32 waypoint_count;
	s32 waygroup_count;
	s32 cover_count;
	const char *stageid;

	if (out_size) {
		*out_size = 0;
	}
	s_clearSourceWidePadOffsets();

	scenario = s_findScenarioForStage(stage, prefer_mp);
	if (!scenario || !s_scenarioPadsPath(scenario, pads_path, sizeof(pads_path))) {
		return NULL;
	}

	text_size = 0;
	text = (char *)fsFileLoad(pads_path, &text_size);
	if (!text || text_size == 0) {
		if (text) {
			free(text);
		}
		if (assetSourceDebugIsEnabledFor(ASSET_SCENARIO)) {
			sysLogPrintf(LOG_ERROR,
				"SCENARIO.SOURCE: missing public pads.json for '%s' at %s",
				scenario->id, pads_path);
		}
		return NULL;
	}

	rows = s_parsePadsJson(text, &row_count);
	free(text);

	if (!rows) {
		if (rows) {
			free(rows);
		}
		sysLogPrintf(LOG_ERROR,
			"SCENARIO.SOURCE: no usable pad rows in public source '%s'",
			pads_path);
		return NULL;
	}

	if (!s_loadNavigationTables(scenario, rows, row_count, pads_path, &nav)) {
		if (rows) {
			free(rows);
		}
		return NULL;
	}

	padfile_size = 0;
	padfile = s_buildPadfile(rows, row_count, &nav, &padfile_size);
	waypoint_count = nav.waypoint_count;
	waygroup_count = nav.waygroup_count;
	cover_count = nav.cover_count;
	free(rows);
	s_freeNavigation(&nav);

	if (!padfile) {
		return NULL;
	}

	stageid = (stage && stage->entry && stage->entry->id[0])
		? stage->entry->id : "?";
	sysLogPrintf(LOG_NOTE,
		"SCENARIO.SOURCE: compiled pads.json '%s' for stage '%s' as %d pads, %d waypoints, %d waygroups, %d covers (%d bytes)",
		pads_path, stageid, row_count,
		waypoint_count, waygroup_count, cover_count, padfile_size);

	if (out_size) {
		*out_size = padfile_size;
	}
	return padfile;
}

/*
 * B-943 (gap #1 part-2): rebuild the BG per-room LIGHT table from the
 * room_lights.json sidecar (schema pd2.scenario.room.lights.v1) emitted by the
 * pdarena extractor. Without this, scenario-source (extracted) stages load with
 * g_BgLightsFileData == NULL and every room->numlights == 0, so the
 * shoot-out-the-lights / dimming mechanic and per-room dynamic brightness are
 * silently dead. The extractor captures every `struct light` field; this loader
 * reconstructs them 1:1 into the flat, room-ordered `struct light` array that
 * dlights.c indexes via room->lightindex (record stride 0x22).
 *
 * Returns a stage-pool buffer of (count * sizeof(struct light)) bytes (the
 * g_BgLightsFileData backing) or NULL when there is no usable light data.
 * *out_count = total light records; *out_max_room = highest roomnum seen. The
 * caller (bgBuildScenarioSourceTables) derives per-room lightindex/numlights
 * from each record's roomnum, mirroring the legacy section-3 light-count walk.
 */
static s32 s_jsonReadIntArrayInRange(const char *start, const char *end,
	const char *key, s32 *out, s32 count)
{
	const char *cursor = s_jsonValueAfterKey(start, end, key);
	s32 i;

	if (!out || !cursor || cursor >= end || *cursor != '[') {
		return 0;
	}
	cursor++;
	for (i = 0; i < count; i++) {
		char *next;
		long value;
		while (cursor < end && isspace((unsigned char)*cursor)) {
			cursor++;
		}
		if (cursor >= end) {
			return 0;
		}
		value = strtol(cursor, &next, 0);
		if (next == cursor || next > end) {
			return 0;
		}
		out[i] = (s32)value;
		cursor = next;
		while (cursor < end && isspace((unsigned char)*cursor)) {
			cursor++;
		}
		if (i < count - 1) {
			if (cursor >= end || *cursor != ',') {
				return 0;
			}
			cursor++;
		}
	}
	while (cursor < end && isspace((unsigned char)*cursor)) {
		cursor++;
	}
	return cursor < end && *cursor == ']';
}

u8 *scenarioSourceLoadRoomLightsForStage(const catalog_stage_result_t *stage,
	s32 prefer_mp, s32 *out_count, s32 *out_max_room)
{
	const asset_entry_t *scenario;
	char lights_path[FS_MAXPATH + 1];
	u32 text_size;
	char *text;
	char *rows_open;
	char *rows_close;
	char *cursor;
	char *text_end;
	s32 capacity = 0;
	s32 count = 0;
	s32 max_room = 0;
	struct light *lights = NULL;
	u8 *data = NULL;
	const char *stageid;

	if (out_count) {
		*out_count = 0;
	}
	if (out_max_room) {
		*out_max_room = 0;
	}

	scenario = s_findScenarioForStage(stage, prefer_mp);
	if (!scenario || !scenario->id[0] ||
			!s_scenarioMemberPath(scenario, "room_lights.json", lights_path,
				sizeof(lights_path))) {
		return NULL;
	}

	text = s_loadOptionalText(lights_path, &text_size);
	if (!text) {
		/* Pre-B943 archives have no room_lights.json: not an error, the legacy
		 * dynamic-light precompute is simply skipped (as it was before). */
		if (assetSourceDebugIsEnabledFor(ASSET_SCENARIO)) {
			sysLogPrintf(LOG_NOTE,
				"SCENARIO.SOURCE: no room_lights.json for '%s' at %s (pre-B943 archive; lights skipped)",
				scenario->id, lights_path);
		}
		return NULL;
	}
	text_end = text + text_size;

	if (!strstr(text, "pd2.scenario.room.lights.v1")) {
		sysLogPrintf(LOG_ERROR,
			"SCENARIO.SOURCE: room_lights.json schema mismatch for '%s' at %s",
			scenario->id, lights_path);
		free(text);
		return NULL;
	}

	rows_open = strstr(text, "\"rows\"");
	if (rows_open) {
		rows_open = strchr(rows_open, '[');
	}
	if (!rows_open) {
		free(text);
		return NULL;
	}
	/* The rows array is the only place '{' objects appear; everything after the
	 * closing ']' ("light_count": N }) is brace-free of '{', so bounding the
	 * row scan by end-of-text is safe and avoids a separate bracket matcher. */
	rows_close = text_end;

	/* First pass: count row objects so we can size the stage allocation once. */
	cursor = rows_open + 1;
	while (cursor < rows_close) {
		char *obj_open = strchr(cursor, '{');
		char *obj_close;
		if (!obj_open || obj_open >= rows_close) {
			break;
		}
		obj_close = s_jsonFindObjectEnd(obj_open, rows_close);
		if (!obj_close) {
			break;
		}
		capacity++;
		cursor = obj_close + 1;
	}

	if (capacity <= 0) {
		free(text);
		if (assetSourceDebugIsEnabledFor(ASSET_SCENARIO)) {
			sysLogPrintf(LOG_NOTE,
				"SCENARIO.SOURCE: room_lights.json has zero lights for '%s'",
				scenario->id);
		}
		return NULL;
	}

	data = mempAlloc(ALIGN16((u32)capacity * (u32)sizeof(struct light)),
		MEMPOOL_STAGE);
	if (!data) {
		sysLogPrintf(LOG_ERROR,
			"SCENARIO.SOURCE: room light allocation failed for '%s' lights=%d",
			scenario->id, capacity);
		free(text);
		return NULL;
	}
	memset(data, 0, ALIGN16((u32)capacity * (u32)sizeof(struct light)));
	lights = (struct light *)data;

	/* Second pass: parse each row object into a struct light. */
	cursor = rows_open + 1;
	while (cursor < rows_close && count < capacity) {
		char *obj_open = strchr(cursor, '{');
		const char *obj_close;
		struct light *l = &lights[count];
		s32 ivalue;
		s32 dir[3] = { 0, 0, 0 };
		s32 bbox[12];
		s32 j;

		if (!obj_open || obj_open >= rows_close) {
			break;
		}
		obj_close = s_jsonFindObjectEnd(obj_open, rows_close);
		if (!obj_close) {
			break;
		}

		if (!s_jsonReadS32Value(obj_open, obj_close, "roomnum", &ivalue)) {
			/* roomnum is mandatory; skip malformed rows rather than abort. */
			cursor = (char *)obj_close + 1;
			continue;
		}
		l->roomnum = (u16)ivalue;
		if (ivalue > max_room) {
			max_room = ivalue;
		}

		if (s_jsonReadS32Value(obj_open, obj_close, "colour", &ivalue)) {
			l->colour = (u16)ivalue;
		}
		if (s_jsonReadS32Value(obj_open, obj_close, "brightness", &ivalue)) {
			l->brightness = (u8)ivalue;
		}
		if (s_jsonReadS32Value(obj_open, obj_close, "sparkable", &ivalue)) {
			l->sparkable = ivalue ? 1 : 0;
		}
		if (s_jsonReadS32Value(obj_open, obj_close, "healthy", &ivalue)) {
			l->healthy = ivalue ? 1 : 0;
		}
		if (s_jsonReadS32Value(obj_open, obj_close, "on", &ivalue)) {
			l->on = ivalue ? 1 : 0;
		}
		if (s_jsonReadS32Value(obj_open, obj_close, "sparking", &ivalue)) {
			l->sparking = ivalue ? 1 : 0;
		}
		if (s_jsonReadS32Value(obj_open, obj_close, "vulnerable", &ivalue)) {
			l->vulnerable = ivalue ? 1 : 0;
		}
		if (s_jsonReadS32Value(obj_open, obj_close, "brightnessmult",
				&ivalue)) {
			l->brightnessmult = (u8)ivalue;
		}
		if (s_jsonReadIntArrayInRange(obj_open, obj_close, "dir", dir, 3)) {
			l->dirx = (s8)dir[0];
			l->diry = (s8)dir[1];
			l->dirz = (s8)dir[2];
		}
		if (s_jsonReadIntArrayInRange(obj_open, obj_close, "bbox", bbox, 12)) {
			for (j = 0; j < 4; j++) {
				l->bbox[j].x = (s16)bbox[j * 3 + 0];
				l->bbox[j].y = (s16)bbox[j * 3 + 1];
				l->bbox[j].z = (s16)bbox[j * 3 + 2];
			}
		}

		count++;
		cursor = (char *)obj_close + 1;
	}

	free(text);

	if (count <= 0) {
		return NULL;
	}

	stageid = (stage && stage->entry && stage->entry->id[0])
		? stage->entry->id : "?";
	sysLogPrintf(LOG_NOTE,
		"SCENARIO.SOURCE: compiled room_lights.json '%s' for stage '%s' as %d lights (max_room=%d, %u bytes)",
		lights_path, stageid, count, max_room,
		(unsigned)((u32)count * (u32)sizeof(struct light)));

	if (out_count) {
		*out_count = count;
	}
	if (out_max_room) {
		*out_max_room = max_room;
	}
	return data;
}
